import jsonschema

problems = []
try:
    jsonschema.validate(tool, tool_schema())
except jsonschema.ValidationError as error:
    return ["tool: " + error.message]

if tool["risk_level"] == "high" and not tool["requires_approval"]:
    problems.append(
        "a high-risk tool always requires approval; this is not configurable"
    )

FORBIDDEN = {"url", "uri", "endpoint", "code", "script", "sql", "command",
             "shell", "path", "filename"}
for name in (tool["input_schema"].get("properties") or {}):
    if name.lower() in FORBIDDEN:
        problems.append(
            "no tool may take %r as an argument; enrichment tools take an "
            "indicator and the connector decides the endpoint" % name
        )

if tool["input_schema"].get("additionalProperties") is not False:
    problems.append(
        "input_schema must set additionalProperties: false, or the argument "
        "surface is unbounded"
    )
return problems

from soar.identity.rbac import has_permission

import jsonschema

# 1. Schema. Arguments are data with a declared shape, not free text.
try:
    jsonschema.validate(arguments, tool["input_schema"])
except jsonschema.ValidationError as error:
    return {"allowed": False, "reason": "arguments: " + error.message}

# 2. Budget. An injected instruction that starts an enrichment loop stops.
if calls_so_far >= tool["max_calls_per_turn"]:
    return {"allowed": False,
            "reason": "per-turn call budget for %s reached" % tool["name"]}

# 3. Scope. The entity must already be on this incident.
if tool.get("scope") == "incident":
    incident_id = session.get("incident_id")
    if not incident_id:
        return {"allowed": False,
                "reason": "%s is incident-scoped and this session has no incident"
                          % tool["name"]}
    for key, value in arguments.items():
        if not (key.endswith("_id") and isinstance(value, str)):
            continue
        known = db.query(
            "SELECT 1 FROM incident_entity WHERE incident_id = %s AND entity_id = %s "
            "UNION ALL SELECT 1 FROM incident_indicator "
            "WHERE incident_id = %s AND indicator_id = %s",
            [incident_id, value, incident_id, value], session["org_id"],
        )
        if not known:
            return {"allowed": False,
                    "reason": "%s=%s is not an entity on this incident"
                              % (key, value)}

# 4. Permission, re-checked at the point of effect rather than trusted from
#    session start - the analyst may have been de-privileged since.
if not has_permission(session.get("permissions") or [], tool["required_permission"]):
    return {"allowed": False,
            "reason": "the AI principal does not hold %s"
                      % tool["required_permission"]}

# 5. Approval. A HIGH tool always requires a human, whoever asked and
#    however it was justified.
if tool["requires_approval"] or tool["risk_level"] == "high":
    return {"allowed": True, "needs_approval": True,
            "risk_level": tool["risk_level"]}

return {"allowed": True, "needs_approval": False,
        "risk_level": tool["risk_level"]}
